-- V91: 작품/아티스트 카탈로그(holy_content) + 성지 링크(holy_content_poi).
-- 생성기: scripts/build_holy_content_seed.py (수동 편집 금지, 재생성으로 갱신)
-- 카탈로그 1024건 / 링크 14969건 — V90 임포트 POI에 연결된 것만.

CREATE TABLE IF NOT EXISTS holy_content (
    content_sqno BIGSERIAL PRIMARY KEY,
    source_ref   VARCHAR(40) UNIQUE NOT NULL,  -- 'kride-artist-{tmp_artist_id}'
    name         VARCHAR(200) NOT NULL,
    name_en      VARCHAR(200),
    category     VARCHAR(20) NOT NULL,         -- kpop | drama | movie | show
    created_at   TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS holy_content_poi (
    link_id      BIGSERIAL PRIMARY KEY,
    content_sqno BIGINT NOT NULL REFERENCES holy_content(content_sqno) ON DELETE CASCADE,
    poi_sqno     BIGINT NOT NULL REFERENCES tour_poi(poi_sqno) ON DELETE CASCADE,
    relationship VARCHAR(40),
    CONSTRAINT uk_holy_content_poi UNIQUE (content_sqno, poi_sqno)
);

CREATE INDEX IF NOT EXISTS idx_holy_content_poi_content ON holy_content_poi(content_sqno);
CREATE INDEX IF NOT EXISTS idx_holy_content_poi_poi ON holy_content_poi(poi_sqno);
CREATE INDEX IF NOT EXISTS idx_holy_content_name ON holy_content(name);

-- 재실행 안전: 링크 → 카탈로그 순서로 비운다.
DELETE FROM holy_content_poi;
DELETE FROM holy_content WHERE source_ref LIKE 'kride-artist-%';

